import { useState } from "react";

type CalendarItem =
  | { type: "empty"; key: string }
  | {
      type: "day";
      key: string;
      day: number;
      date: Date;
      isDisabled: boolean;
      isSelected: boolean;
    };

export function App() {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [currentDate, setCurrentDate] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [selectedTime, setSelectedTime] = useState<string | null>(null);

  const availableTimeSlots = ["10:00", "11:00", "14:00", "15:00", "16:00", "18:00"];

  const redirectToBank = (amount: string, comment: string) => {
    const recipientName = "Zsebeházi Andrea";
    const accountNumber = "107000314973750951100005";
    const isMobile = /iPhone|iPad|iPod|Android/i.test(navigator.userAgent);

    if (isMobile) {
      const bankLink = otpbank://payment?account=${accountNumber}&amount=${amount}&name=${encodeURIComponent(
        recipientName
      )}&message=${encodeURIComponent(comment)};
      window.location.href = bankLink;
    } else {
      alert(
        "Az automatikus átirányítás csak mobil eszközön működik. Kérjük, nyisd meg az oldalt a telefonodon."
      );
    }
  };

  const handlePurchase = () => {
    redirectToBank("10000", "Zsebibaba Kis Csomag");
  };

  const handleBookingConfirm = () => {
    if (!selectedDate || !selectedTime) return;

    const formattedDate = ${selectedDate.getFullYear()}.${String(selectedDate.getMonth() + 1).padStart(
      2,
      "0"
    )}.${String(selectedDate.getDate()).padStart(2, "0")};
    const comment = Időpont: ${formattedDate} ${selectedTime};

    redirectToBank("25000", comment);
    setIsModalOpen(false);
  };

  const changeMonth = (delta: number) => {
    const newDate = new Date(currentDate);
    newDate.setMonth(newDate.getMonth() + delta);
    setCurrentDate(newDate);
  };

  const getCalendarDays = (): CalendarItem[] => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDayOfMonth = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const firstDayIndex = firstDayOfMonth === 0 ? 6 : firstDayOfMonth  1;

    const days: CalendarItem[] = [];
    for (let i = 0; i < firstDayIndex; i += 1) {
      days.push({ type: "empty", key: empty-${i} });
    }

    const now = new Date();
    now.setHours(0, 0, 0, 0);

    for (let day = 1; day <= daysInMonth; day += 1) {
      const date = new Date(year, month, day);
      days.push({
        type: "day",
        key: day-${day},
        day,
        date,
        isDisabled: date < now,
        isSelected: selectedDate?.toDateString() === date.toDateString(),
      });
    }

    return days;
  };

  const monthName = new Intl.DateTimeFormat("huHU", { month: "long" }).format(currentDate);
  const displayMonthYear = ${currentDate.getFullYear()}. ${monthName};

  return (
    <>
      <style>{
        , ::before, ::after { boxsizing: borderbox; margin: 0; padding: 0; }
        html { webkittextsizeadjust: 100%; webkittaphighlightcolor: transparent; }
        body { fontfamily: applesystem, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sansserif; webkitfontsmoothing: antialiased; background: 000; color: f5f5f7; overflowx: hidden; position: relative; minheight: 100vh; }
        bgvideo { position: fixed; right: 0; bottom: 0; minwidth: 100%; minheight: 100%; width: auto; height: auto; zindex: 100; objectfit: cover; filter: blur(12px) brightness(0.7); }
        header { position: absolute; top: 0; left: 0; right: 0; textalign: center; padding: 1.5rem 0; zindex: 10; display: flex; flexdirection: column; alignitems: center; gap: 0.3rem; }
        h1 { fontsize: 2.5rem; fontweight: 700; letterspacing: 0.05em; color: fff; }
        .container { minheight: 100vh; display: flex; flexdirection: column; alignitems: center; justifycontent: center; padding: 1rem; gap: 1rem; }
        .headerbookingbtn { margintop: 0.2rem; padding: 0.6rem 1.2rem !important; fontsize: 0.9rem !important; }
        .glasscard { background: rgba(28, 28, 30, 0.75); backdropfilter: blur(25px); webkitbackdropfilter: blur(25px); borderradius: 1.5rem; border: 1px solid rgba(255, 255, 255, 0.12); boxshadow: 0 16px 48px rgba(0, 0, 0, 0.3); width: 18rem; height: 18rem; padding: 1rem; display: flex; flexdirection: column; alignitems: center; justifycontent: center; textalign: center; transform: scale(0.49); margintop: 5rem; marginbottom: 5rem; }
        .glasscard h2 { fontsize: 2.2rem; fontweight: 700; marginbottom: 0.5rem; color: fff; }
        .glasscard p { fontsize: 1.6rem; fontweight: 600; color: fff; marginbottom: 1rem; }
        .buttonprimary, .buttonsecondary { border: none; cursor: pointer; transition: transform 0.2s, backgroundcolor 0.2s; fontsize: 1rem; outline: none; webkittaphighlightcolor: transparent; touchaction: manipulation; fontweight: 500; borderradius: 9999px; color: fff; }
        .buttonprimary { background: 0a84ff; padding: 0.875rem 1.75rem; }
        .buttonprimary:hover { transform: scale(1.05); background: 359aff; }
        .buttonprimary:active { transform: scale(0.98); }
        .buttonprimary:disabled { opacity: 0.5; cursor: notallowed; transform: none; }
        .buttonsecondary { background: rgba(255, 255, 255, 0.15); padding: 0.8rem 1.8rem; fontsize: 1.2rem; fontweight: 600; }
        .buttonsecondary:hover { transform: scale(1.05); background: rgba(255, 255, 255, 0.25); }
        .modal { position: fixed; inset: 0; background: rgba(0, 0, 0, 0.5); display: flex; alignitems: center; justifycontent: center; padding: 1rem; zindex: 50; opacity: 0; visibility: hidden; transition: opacity 0.3s ease, visibility 0.3s ease; }
        .modal.active { opacity: 1; visibility: visible; }
        .modalcontent { background: rgba(28, 28, 30, 0.75); backdropfilter: blur(25px); webkitbackdropfilter: blur(25px); borderradius: 1.5rem; border: 1px solid rgba(255, 255, 255, 0.12); boxshadow: 0 16px 48px rgba(0, 0, 0, 0.3); width: 100%; maxwidth: 32rem; padding: 2rem; animation: modalFadeIn 0.3s ease forwards; }
        @keyframes modalFadeIn { from { opacity: 0; transform: translateY(20px); } to { opacity: 1; transform: translateY(0); } }
        .modalheader { display: flex; justifycontent: spacebetween; alignitems: center; marginbottom: 1.5rem; }
        .modalheader h3 { fontsize: 1.5rem; fontweight: 700; }
        .closebtn { background: none; border: none; color: 8e8e93; cursor: pointer; fontsize: 2rem; lineheight: 1; padding: 0; width: 2rem; height: 2rem; display: flex; alignitems: center; justifycontent: center; transition: color 0.2s; outline: none; webkittaphighlightcolor: transparent; }
        .closebtn:hover { color: fff; }
        .calendarnav { display: flex; justifycontent: spacebetween; alignitems: center; marginbottom: 1rem; }
        .calendarnav button { background: none; border: none; color: f5f5f7; cursor: pointer; padding: 0.5rem; borderradius: 9999px; transition: background 0.2s; outline: none; webkittaphighlightcolor: transparent; }
        .calendarnav button:hover { background: rgba(255, 255, 255, 0.1); }
        .calendargrid { display: grid; gridtemplatecolumns: repeat(7, 1fr); gap: 0.5rem; }
        .weekday, .calendarday { display: flex; justifycontent: center; alignitems: center; aspectratio: 1/1; }
        .weekday { fontweight: 500; fontsize: 0.8rem; color: rgba(235, 235, 245, 0.6); }
        .calendarday { cursor: pointer; borderradius: 9999px; transition: backgroundcolor 0.2s; outline: none; webkittaphighlightcolor: transparent; }
        .calendarday.selected { background: 0a84ff; color: fff; fontweight: 600; }
        .calendarday.disabled { opacity: 0.35; cursor: notallowed; pointerevents: none; }
        .timeslotscontainer { margintop: 1.5rem; display: none; }
        .timeslotscontainer.active { display: block; }
        .timeslots { display: grid; gridtemplatecolumns: repeat(3, 1fr); gap: 0.75rem; }
        .timeslot { cursor: pointer; border: 1px solid rgba(255, 255, 255, 0.2); textalign: center; padding: 0.5rem; borderradius: 0.5rem; transition: backgroundcolor 0.2s; }
        .timeslot.selected { background: 0a84ff; color: fff; }
        .confirmbtn { width: 100%; margintop: 2rem; }
        @media(minwidth:640px) { h1 { fontsize: 3rem; } }
      }</style>
      <video autoPlay muted loop playsInline id="bgvideo">
        <source src="" type="video/mp4" />
      </video>

      <header>
        <h1>Zsebibaba</h1>
        <button
          className="buttonprimary headerbookingbtn"
          onClick={() => {
            setCurrentDate(new Date());
            setSelectedDate(null);
            setSelectedTime(null);
            setIsModalOpen(true);
          }}
        >
          Időpontfoglalás (25 000 Ft)
        </button>
      </header>

      <div className="container">
        <div className="glasscard">
          <h2>Kis csomag</h2>
          <p>10 000 Ft</p>
          <button className="buttonsecondary" onClick={handlePurchase}>
            Vásárlás
          </button>
        </div>
      </div>

      <div
        className={modal ${isModalOpen ? "active" : ""}}
        onClick={(event) => {
          if (event.target === event.currentTarget) setIsModalOpen(false);
        }}
      >
        <div className="modalcontent">
          <div className="modalheader">
            <h3>Időpontfoglalás</h3>
            <button className="closebtn" onClick={() => setIsModalOpen(false)}>
              ×
            </button>
          </div>
          <div>
            <div className="calendarnav">
              <button onClick={() => changeMonth(1)} arialabel="Előző hónap">
                <svg style={{ width: "1.5rem", height: "1.5rem" }} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M15 19l77 77" />
                </svg>
              </button>
              <h4>{displayMonthYear}</h4>
              <button onClick={() => changeMonth(1)} arialabel="Következő hónap">
                <svg style={{ width: "1.5rem", height: "1.5rem" }} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 77 7" />
                </svg>
              </button>
            </div>
            <div className="calendargrid">
              <div className="weekday">H</div>
              <div className="weekday">K</div>
              <div className="weekday">Sze</div>
              <div className="weekday">Cs</div>
              <div className="weekday">P</div>
              <div className="weekday">Szo</div>
              <div className="weekday">V</div>
            </div>
            <div className="calendargrid">
              {getCalendarDays().map((item) => {
                if (item.type === "empty") {
                  return <div key={item.key} className="calendarday empty"></div>;
                }

