                  <div
                    key={item.key}
                    className={calendarday ${item.isDisabled ? "disabled" : ""} ${
                      item.isSelected ? "selected" : ""
                    }}
                    onClick={() => {
                      if (!item.isDisabled) {
                        setSelectedDate(item.date);
                        setSelectedTime(null);
                      }
                    }}
                  >
                    {item.day}
                  </div>
