        if (!crossmintRoot) {
          crossmintRoot = ReactDOM.createRoot(crossmintMount);
        }
        crossmintRoot.render(React.createElement(CheckoutApp, { payload: payload, onClose: closeCrossmintModal }));
      }

      async function handlePurchase() {
        const purchaseId = uuid();
        const payload = {
          kind: "small",
          totalPrice: "10000",
          metadata: {
            purchaseId: purchaseId,
            product: "kis_csomag",
            amount_huf: 10000,
            createdAt: new Date().toISOString()
          }
