        const formattedDate = formatDateHu(state.selectedDate);
        const payload = {
          kind: "booking",
          totalPrice: "25000",
          metadata: {
            purchaseId: purchaseId,
            product: "idopontfoglalas",
            amount_huf: 25000,
            booking_date: formattedDate,
            booking_time: state.selectedTime,
            createdAt: new Date().toISOString()
          }
        };
        closeModal();
        await openCrossmintCheckout(payload);
