python
import hashlib
import hmac
import json
import os
import sqlite3
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, Optional

from fastapi import FastAPI, Header, HTTPException, Request, Response
from fastapi.middleware.cors import CORSMiddleware
from fastapi.middleware.gzip import GZipMiddleware
from fastapi.responses import FileResponse, JSONResponse, PlainTextResponse
from starlette.middleware.trustedhost import TrustedHostMiddleware

APP_DIR = Path(__file__).resolve().parent
DB_PATH = APP_DIR / "data.db"

CROSSMINT_CLIENT_API_KEY = os.environ.get("CROSSMINT_CLIENT_API_KEY", "").strip()
CROSSMINT_COLLECTION_ID_SMALL = os.environ.get("CROSSMINT_COLLECTION_ID_SMALL", "").strip()
CROSSMINT_COLLECTION_ID_BOOKING = os.environ.get("CROSSMINT_COLLECTION_ID_BOOKING", "").strip()
CROSSMINT_WEBHOOK_SECRET = os.environ.get("CROSSMINT_WEBHOOK_SECRET", "").strip()
FIAT_CURRENCY = os.environ.get("FIAT_CURRENCY", "eur").strip().lower()
LOCALE = os.environ.get("LOCALE", "hu-HU").strip()

INDEX_HTML_PATH = APP_DIR / "index.html"
WELL_KNOWN_DIR = APP_DIR / ".well-known"
APPLE_PAY_FILE_PATH = WELL_KNOWN_DIR / "apple-developer-merchantid-domain-association"
APPLE_PAY_FILE_ENV = os.environ.get("APPLE_DEVELOPER_MERCHANTID_DOMAIN_ASSOCIATION", "")

TRUSTED_HOSTS = os.environ.get("TRUSTED_HOSTS", "").strip()
ALLOWED_ORIGINS = os.environ.get("ALLOWED_ORIGINS", "*").strip()


def utc_now_iso() -> str:
  return datetime.now(timezone.utc).isoformat()


def db_connect() -> sqlite3.Connection:
  conn = sqlite3.connect(str(DB_PATH), isolation_level=None, check_same_thread=False, timeout=10.0)
  conn.execute("PRAGMA journal_mode=WAL;")
  conn.execute("PRAGMA synchronous=NORMAL;")
  conn.execute("PRAGMA foreign_keys=ON;")
  conn.execute("PRAGMA temp_store=MEMORY;")
  conn.execute("PRAGMA cache_size=-64000;")
  return conn


def db_init() -> None:
  conn = db_connect()
  try:
    conn.execute(
      """
      CREATE TABLE IF NOT EXISTS webhook_events (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        event_type TEXT NOT NULL,
        signature_header TEXT,
        payload_json TEXT NOT NULL,
        received_at_utc TEXT NOT NULL
      );
      """
    )
    conn.execute("CREATE INDEX IF NOT EXISTS idx_webhook_events_type ON webhook_events(event_type);")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_webhook_events_received_at ON webhook_events(received_at_utc);")
    conn.execute(
      """
      CREATE TABLE IF NOT EXISTS order_events (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        order_identifier TEXT,
        event_type TEXT NOT NULL,
        payment_method_type TEXT,
        total_amount TEXT,
        total_currency TEXT,
        tx_id TEXT,
        contract_address TEXT,
        token_ids_json TEXT,
        recipient_wallet_address TEXT,
        metadata_json TEXT,
        raw_payload_json TEXT NOT NULL,
        received_at_utc TEXT NOT NULL
      );
      """
    )
    conn.execute("CREATE INDEX IF NOT EXISTS idx_order_events_order_id ON order_events(order_identifier);")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_order_events_event_type ON order_events(event_type);")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_order_events_received_at ON order_events(received_at_utc);")
  finally:
    conn.close()


app = FastAPI(
  title="Zsebibaba Payment API",
  version="1.0.0",
  docs_url=None,
  redoc_url=None,
  openapi_url=None
)

app.add_middleware(GZipMiddleware, minimum_size=500)

if ALLOWED_ORIGINS != "*":
  origins = [o.strip() for o in ALLOWED_ORIGINS.split(",") if o.strip()]
  app.add_middleware(
    CORSMiddleware,
    allow_origins=origins,
    allow_credentials=True,
    allow_methods=["GET", "POST", "OPTIONS"],
    allow_headers=["*"],
    max_age=3600
  )
else:
  app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=False,
    allow_methods=["GET", "POST", "OPTIONS"],
    allow_headers=["*"],
    max_age=3600
  )

if TRUSTED_HOSTS:
  hosts = [h.strip() for h in TRUSTED_HOSTS.split(",") if h.strip()]
  if hosts:
    app.add_middleware(TrustedHostMiddleware, allowed_hosts=hosts)


@app.on_event("startup")
async def startup_event() -> None:
  db_init()
  WELL_KNOWN_DIR.mkdir(parents=True, exist_ok=True)
  if APPLE_PAY_FILE_ENV and not APPLE_PAY_FILE_PATH.exists():
    try:
      APPLE_PAY_FILE_PATH.write_text(APPLE_PAY_FILE_ENV, encoding="utf-8")
    except Exception:
      pass


@app.get("/api/config")
async def api_config() -> JSONResponse:
  if not CROSSMINT_CLIENT_API_KEY:
    raise HTTPException(status_code=500, detail="CROSSMINT_CLIENT_API_KEY missing")
  if not CROSSMINT_COLLECTION_ID_SMALL:
    raise HTTPException(status_code=500, detail="CROSSMINT_COLLECTION_ID_SMALL missing")
  if not CROSSMINT_COLLECTION_ID_BOOKING:
    raise HTTPException(status_code=500, detail="CROSSMINT_COLLECTION_ID_BOOKING missing")

  allowed_currencies = ["usd", "eur", "gbp", "cad", "aud", "jpy", "chf"]
  if FIAT_CURRENCY not in allowed_currencies:
    currency = "eur"
  else:
    currency = FIAT_CURRENCY

  return JSONResponse(
    {
      "crossmintClientApiKey": CROSSMINT_CLIENT_API_KEY,
      "crossmintCollectionIdSmall": CROSSMINT_COLLECTION_ID_SMALL,
      "crossmintCollectionIdBooking": CROSSMINT_COLLECTION_ID_BOOKING,
      "fiatCurrency": currency,
      "locale": LOCALE,
    },
    headers={
      "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
      "Pragma": "no-cache",
      "Expires": "0"
    },
  )


@app.get("/")
async def index() -> FileResponse:
  if not INDEX_HTML_PATH.exists():
    raise HTTPException(status_code=404, detail="index.html not found")
  return FileResponse(
    INDEX_HTML_PATH,
    media_type="text/html; charset=utf-8",
    headers={
      "Cache-Control": "public, max-age=300",
      "X-Content-Type-Options": "nosniff"
    }
  )


@app.get("/.well-known/apple-developer-merchantid-domain-association")
async def apple_pay_domain_association() -> Response:
  if APPLE_PAY_FILE_PATH.exists():
    return FileResponse(
      APPLE_PAY_FILE_PATH,
      media_type="text/plain; charset=utf-8",
      headers={
        "Cache-Control": "public, max-age=86400",
        "X-Content-Type-Options": "nosniff"
      }
    )
  if APPLE_PAY_FILE_ENV:
    return PlainTextResponse(
      APPLE_PAY_FILE_ENV,
      media_type="text/plain; charset=utf-8",
      headers={
        "Cache-Control": "public, max-age=86400",
        "X-Content-Type-Options": "nosniff"
      }
    )
  raise HTTPException(status_code=404, detail="Apple Pay domain association file not configured")


def verify_webhook_signature(payload: bytes, signature_header: str, secret: str) -> bool:
  if not signature_header or not secret:
    return False
  try:
    computed_signature = hmac.new(
      secret.encode("utf-8"),
      payload,
      hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(computed_signature, signature_header)
  except Exception:
    return False


def extract_order_fields(payload: Dict[str, Any]) -> Dict[str, Optional[str]]:
  order_identifier = None
  payment_method_type = None
  total_amount = None
  total_currency = None
  tx_id = None
  contract_address = None
  token_ids_json = None
  recipient_wallet_address = None
  metadata_json = None

  if isinstance(payload, dict):
    oi = payload.get("orderIdentifier")
    if oi is None:
      oi = payload.get("orderId")
    if isinstance(oi, str):
      order_identifier = oi

    pmt = payload.get("paymentMethodType")
    if pmt is None:
      pmt = payload.get("payment")
    if isinstance(pmt, str):
      payment_method_type = pmt
    elif isinstance(pmt, dict):
      method_type = pmt.get("method")
      if isinstance(method_type, str):
        payment_method_type = method_type

    tp = payload.get("totalPrice")
    if tp is None:
      tp = payload.get("price")
    if isinstance(tp, dict):
      amt = tp.get("amount")
      cur = tp.get("currency")
      if isinstance(amt, (str, int, float)):
        total_amount = str(amt)
      if isinstance(cur, str):
        total_currency = cur
    elif isinstance(tp, (str, int, float)):
      total_amount = str(tp)

    tx = payload.get("txId")
    if tx is None:
      tx = payload.get("transactionId")
    if tx is None:
      tx = payload.get("transaction_id")
    if isinstance(tx, str):
      tx_id = tx

    ca = payload.get("contractAddress")
    if ca is None:
      ca = payload.get("contract_address")
    if isinstance(ca, str):
      contract_address = ca

    tids = payload.get("tokenIds")
    if tids is None:
      tids = payload.get("token_ids")
    if isinstance(tids, list):
      token_ids_json = json.dumps([str(x) for x in tids], separators=(",", ":"))

    rec = payload.get("recipient")
    if isinstance(rec, dict):
      wa = rec.get("walletAddress")
      if wa is None:
        wa = rec.get("wallet_address")
      if isinstance(wa, str):
        recipient_wallet_address = wa

    wa2 = payload.get("walletAddress")
    if wa2 is None:
      wa2 = payload.get("wallet_address")
    if isinstance(wa2, str) and not recipient_wallet_address:
      recipient_wallet_address = wa2

    md = payload.get("metadata")
    if isinstance(md, dict):
      metadata_json = json.dumps(md, separators=(",", ":"), ensure_ascii=False)

  return {
    "order_identifier": order_identifier,
    "payment_method_type": payment_method_type,
    "total_amount": total_amount,
    "total_currency": total_currency,
    "tx_id": tx_id,
    "contract_address": contract_address,
    "token_ids_json": token_ids_json,
    "recipient_wallet_address": recipient_wallet_address,
    "metadata_json": metadata_json
  }


@app.post("/webhooks/crossmint")
async def crossmint_webhook(
  request: Request,
  x_crossmint_signature: Optional[str] = Header(default=None, alias="x-crossmint-signature")
) -> JSONResponse:
  if not CROSSMINT_WEBHOOK_SECRET:
    raise HTTPException(status_code=500, detail="CROSSMINT_WEBHOOK_SECRET missing")

  raw_body = await request.body()

  if not x_crossmint_signature:
    raise HTTPException(status_code=400, detail="Missing x-crossmint-signature header")

  is_valid = verify_webhook_signature(raw_body, x_crossmint_signature, CROSSMINT_WEBHOOK_SECRET)
  if not is_valid:
    raise HTTPException(status_code=401, detail="Invalid webhook signature")

  try:
    payload_str = raw_body.decode("utf-8")
  except Exception:
    raise HTTPException(status_code=400, detail="Invalid body encoding")

  try:
    webhook_obj = json.loads(payload_str)
  except Exception:
    raise HTTPException(status_code=400, detail="Invalid JSON payload")

  if not isinstance(webhook_obj, dict):
    raise HTTPException(status_code=400, detail="Invalid payload type")

  event_type = webhook_obj.get("type")
  if event_type is None:
    event_type = webhook_obj.get("event")
  if event_type is None:
    event_type = webhook_obj.get("eventType")
  if not isinstance(event_type, str) or not event_type:
    raise HTTPException(status_code=400, detail="Missing event type")

  payload = webhook_obj.get("payload")
  if payload is None:
    payload = webhook_obj.get("data")
  if payload is None:
    payload = webhook_obj

  received_at = utc_now_iso()

  conn = db_connect()
  try:
    conn.execute(
      """
      INSERT INTO webhook_events (event_type, signature_header, payload_json, received_at_utc)
      VALUES (?, ?, ?, ?)
      """,
      (
        event_type,
        x_crossmint_signature,
        json.dumps(webhook_obj, separators=(",", ":"), ensure_ascii=False),
        received_at
      ),
    )

    fields = extract_order_fields(payload if isinstance(payload, dict) else {})
    conn.execute(
      """
      INSERT INTO order_events (
        order_identifier,
        event_type,
        payment_method_type,
        total_amount,
        total_currency,
        tx_id,
        contract_address,
        token_ids_json,
        recipient_wallet_address,
        metadata_json,
        raw_payload_json,
        received_at_utc
      )
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      """,
      (
        fields["order_identifier"],
        event_type,
        fields["payment_method_type"],
        fields["total_amount"],
        fields["total_currency"],
        fields["tx_id"],
        fields["contract_address"],
        fields["token_ids_json"],
        fields["recipient_wallet_address"],
        fields["metadata_json"],
        json.dumps(payload, separators=(",", ":"), ensure_ascii=False) if payload is not None else "{}",
        received_at,
      ),
    )
  finally:
    conn.close()

  return JSONResponse(
    {"status": "success", "receivedAt": received_at},
    headers={
      "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
      "Pragma": "no-cache"
    }
  )


@app.get("/admin/events")
async def admin_events(limit: int = 50) -> JSONResponse:
  if limit < 1:
    raise HTTPException(status_code=400, detail="limit must be >= 1")
  if limit > 500:
    limit = 500
  conn = db_connect()
  try:
    rows = conn.execute(
      """
      SELECT
        id,
        order_identifier,
        event_type,
        payment_method_type,
        total_amount,
        total_currency,
        tx_id,
        recipient_wallet_address,
        metadata_json,
        received_at_utc
      FROM order_events
      ORDER BY id DESC
      LIMIT ?
      """,
      (limit,),
    ).fetchall()
  finally:
    conn.close()

  events = []
  for r in rows:
    metadata = None
    if r[8]:
      try:
        metadata = json.loads(r[8])
      except Exception:
        metadata = None

    events.append(
      {
        "id": r[0],
        "orderIdentifier": r[1],
        "type": r[2],
        "paymentMethodType": r[3],
        "total": {"amount": r[4], "currency": r[5]},
        "txId": r[6],
        "recipientWalletAddress": r[7],
        "metadata": metadata,
        "receivedAtUtc": r[9],
      }
    )
  return JSONResponse(
    {"events": events, "count": len(events)},
    headers={
      "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
      "Pragma": "no-cache"
    }
  )


@app.get("/health")
async def health() -> JSONResponse:
  db_ok = False
  try:
    conn = db_connect()
    conn.execute("SELECT 1").fetchone()
    conn.close()
    db_ok = True
  except Exception:
    db_ok = False

  return JSONResponse(
    {
      "ok": True,
      "database": db_ok,
      "timeUtc": utc_now_iso()
    },
    headers={
      "Cache-Control": "no-store, no-cache, must-revalidate, max-age=0",
      "Pragma": "no-cache"
    }
  )


if __name__ == "__main__":
  import uvicorn
  port = int(os.environ.get("PORT", "3000"))
  uvicorn.run(
    "main:app",
    host="0.0.0.0",
    port=port,
    log_level="info",
    access_log=True,
    workers=1
  )

