    @media (min-width: 640px) { h1 { font-size: 3rem; } }
    @media (prefers-reduced-motion: reduce) {
      .button-primary, .button-secondary, .calendar-day, .time-slot, .modal { transition: none; }
      .modal-content { animation: none; }
    }
  </style>
