<body>
  <video autoplay muted loop playsinline id="bg-video" preload="auto">
    <source src="https://zsebibabakutya.univer.se/_api/v1/videos/321224/stream" type="video/mp4">
  </video>

  <header>
    <h1>Zsebibaba</h1>
    <button id="openBooking" class="button-primary header-booking-btn" type="button">Időpontfoglalás (25 000 Ft)</button>
  </header>

  <main class="container">
    <div class="glass-card" aria-label="Kis csomag">
      <h2>Kis csomag</h2>
      <p>10 000 Ft</p>
      <button id="purchaseSmall" class="button-secondary" type="button">Vásárlás</button>
    </div>
  </main>

  <div id="bookingModal" class="modal" role="dialog" aria-modal="true" aria-labelledby="modalTitle" aria-hidden="true">
    <div id="modalContent" class="modal-content" role="document" tabindex="-1">
      <div class="modal-header">
        <h3 id="modalTitle">Időpontfoglalás</h3>
        <button id="closeModal" class="close-btn" type="button" aria-label="Bezárás">×</button>
      </div>

      <div>
        <div class="calendar-nav">
          <button id="prevMonth" type="button" aria-label="Előző hónap">
            <svg style="width: 1.5rem; height: 1.5rem" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7"></path>
            </svg>
          </button>
          <h4 id="monthYear"></h4>
          <button id="nextMonth" type="button" aria-label="Következő hónap">
            <svg style="width: 1.5rem; height: 1.5rem" fill="none" stroke="currentColor" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
              <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7"></path>
            </svg>
          </button>
        </div>

        <div class="calendar-grid" aria-hidden="true">
          <div class="weekday">H</div>
          <div class="weekday">K</div>
          <div class="weekday">Sze</div>
          <div class="weekday">Cs</div>
          <div class="weekday">P</div>
          <div class="weekday">Szo</div>
          <div class="weekday">V</div>
        </div>

        <div id="daysGrid" class="calendar-grid" role="grid" aria-label="Naptár"></div>
      </div>

      <div id="timeSlotsContainer" class="time-slots-container">
        <h4>Válassz időpontot:</h4>
        <div id="timeSlots" class="time-slots" role="list"></div>
      </div>

      <button id="confirmBooking" class="button-primary confirm-btn" type="button" disabled>Fizetés (25 000 Ft)</button>
    </div>
  </div>

  <div id="crossmintModal" class="modal" role="dialog" aria-modal="true" aria-labelledby="crossmintTitle" aria-hidden="true">
    <div id="crossmintContent" class="modal-content" role="document" tabindex="-1">
      <div class="modal-header">
        <h3 id="crossmintTitle">Fizetés</h3>
        <button id="closeCrossmint" class="close-btn" type="button" aria-label="Bezárás">×</button>
      </div>
      <div id="crossmintMount" class="crossmint-container"></div>
    </div>
  </div>

  <script src="https://unpkg.com/react@18.2.0/umd/react.production.min.js" crossorigin></script>
  <script src="https://unpkg.com/react-dom@18.2.0/umd/react-dom.production.min.js" crossorigin></script>
  <script src="https://unpkg.com/@crossmint/client-sdk-react-ui@1.11.2/dist/umd/index.global.js" crossorigin></script>

  <script>
    (function () {
      const React = window.React;
      const ReactDOM = window.ReactDOM;
      const CrossmintGlobal = window.CrossmintClientSdkReactUi;

      if (!React || !ReactDOM || !CrossmintGlobal) {
        return;
      }

      const CrossmintProvider = CrossmintGlobal.CrossmintProvider;
      const CrossmintCheckoutProvider = CrossmintGlobal.CrossmintCheckoutProvider;
      const CrossmintEmbeddedCheckout = CrossmintGlobal.CrossmintEmbeddedCheckout;
      const useCrossmintCheckout = CrossmintGlobal.useCrossmintCheckout;

      const availableTimeSlots = ["10:00", "11:00", "14:00", "15:00", "16:00", "18:00"];
      const state = {
        isModalOpen: false,
        currentDate: new Date(),
        selectedDate: null,
        selectedTime: null
      };

      const openBookingButton = document.getElementById("openBooking");
      const purchaseSmallButton = document.getElementById("purchaseSmall");
      const bookingModal = document.getElementById("bookingModal");
      const modalContent = document.getElementById("modalContent");
      const closeModalButton = document.getElementById("closeModal");
      const prevMonthButton = document.getElementById("prevMonth");
      const nextMonthButton = document.getElementById("nextMonth");
      const monthYearEl = document.getElementById("monthYear");
      const daysGrid = document.getElementById("daysGrid");
      const timeSlotsContainer = document.getElementById("timeSlotsContainer");
      const timeSlotsEl = document.getElementById("timeSlots");
      const confirmBookingButton = document.getElementById("confirmBooking");

      const crossmintModal = document.getElementById("crossmintModal");
      const crossmintContent = document.getElementById("crossmintContent");
      const closeCrossmintButton = document.getElementById("closeCrossmint");
      const crossmintMount = document.getElementById("crossmintMount");

      let lastFocusedElement = null;
      let trapHandlerBound = null;
      let lastFocusedElementCrossmint = null;
      let trapHandlerCrossmintBound = null;

      let crossmintRoot = null;
      let configCache = null;

      function setNoScroll(enabled) {
        if (enabled) {
          document.documentElement.style.overflow = "hidden";
          document.body.style.overflow = "hidden";
        } else {
          document.documentElement.style.overflow = "";
          document.body.style.overflow = "";
        }
      }

      function pad2(value) {
        const s = String(value);
        return s.length >= 2 ? s : "0" + s;
      }

      function formatDateHu(dateObj) {
        const y = dateObj.getFullYear();
        const m = pad2(dateObj.getMonth() + 1);
        const d = pad2(dateObj.getDate());
        return y + "." + m + "." + d;
      }

      function openModal() {
        if (state.isModalOpen) return;
        lastFocusedElement = document.activeElement instanceof HTMLElement ? document.activeElement : null;
        state.isModalOpen = true;
        const now = new Date();
        state.currentDate = new Date(now.getFullYear(), now.getMonth(), 1);
        state.selectedDate = null;
        state.selectedTime = null;
        bookingModal.classList.add("active");
        bookingModal.setAttribute("aria-hidden", "false");
        setNoScroll(true);
        render();
        setTimeout(function () {
          modalContent.focus();
        }, 0);
        enableFocusTrap();
      }

      function closeModal() {
        if (!state.isModalOpen) return;
        state.isModalOpen = false;
        bookingModal.classList.remove("active");
        bookingModal.setAttribute("aria-hidden", "true");
        setNoScroll(false);
        disableFocusTrap();
        if (lastFocusedElement && document.contains(lastFocusedElement)) {
          lastFocusedElement.focus();
        }
      }

      function enableFocusTrap() {
        if (trapHandlerBound) return;
        trapHandlerBound = function (event) {
          if (!state.isModalOpen) return;
          if (event.key === "Escape") {
            event.preventDefault();
            closeModal();
            return;
          }
          if (event.key !== "Tab") return;
          const focusable = bookingModal.querySelectorAll("button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex='-1'])");
          if (!focusable.length) {
            event.preventDefault();
            modalContent.focus();
            return;
          }
          const first = focusable[0];
          const last = focusable[focusable.length - 1];
          const active = document.activeElement;
          if (event.shiftKey) {
            if (active === first || active === bookingModal) {
              event.preventDefault();
              last.focus();
            }
          } else {
            if (active === last) {
              event.preventDefault();
              first.focus();
            }
          }
        };
        document.addEventListener("keydown", trapHandlerBound, true);
      }

      function disableFocusTrap() {
        if (!trapHandlerBound) return;
        document.removeEventListener("keydown", trapHandlerBound, true);
        trapHandlerBound = null;
      }

      function openCrossmintModal() {
        if (crossmintModal.classList.contains("active")) return;
        lastFocusedElementCrossmint = document.activeElement instanceof HTMLElement ? document.activeElement : null;
        crossmintModal.classList.add("active");
        crossmintModal.setAttribute("aria-hidden", "false");
        setNoScroll(true);
        setTimeout(function () {
          crossmintContent.focus();
        }, 0);
        enableFocusTrapCrossmint();
      }

      function closeCrossmintModal() {
        if (!crossmintModal.classList.contains("active")) return;
        crossmintModal.classList.remove("active");
        crossmintModal.setAttribute("aria-hidden", "true");
        setNoScroll(false);
        disableFocusTrapCrossmint();
        if (lastFocusedElementCrossmint && document.contains(lastFocusedElementCrossmint)) {
          lastFocusedElementCrossmint.focus();
        }
        if (crossmintRoot) {
          crossmintRoot.unmount();
          crossmintRoot = null;
        }
        while (crossmintMount.firstChild) {
          crossmintMount.removeChild(crossmintMount.firstChild);
        }
      }

      function enableFocusTrapCrossmint() {
        if (trapHandlerCrossmintBound) return;
        trapHandlerCrossmintBound = function (event) {
          if (!crossmintModal.classList.contains("active")) return;
          if (event.key === "Escape") {
            event.preventDefault();
            closeCrossmintModal();
            return;
          }
          if (event.key !== "Tab") return;
          const focusable = crossmintModal.querySelectorAll("button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex='-1'])");
          if (!focusable.length) {
            event.preventDefault();
            crossmintContent.focus();
            return;
          }
          const first = focusable[0];
          const last = focusable[focusable.length - 1];
          const active = document.activeElement;
          if (event.shiftKey) {
            if (active === first || active === crossmintModal) {
              event.preventDefault();
              last.focus();
            }
          } else {
            if (active === last) {
              event.preventDefault();
              first.focus();
            }
          }
        };
        document.addEventListener("keydown", trapHandlerCrossmintBound, true);
      }

      function disableFocusTrapCrossmint() {
        if (!trapHandlerCrossmintBound) return;
        document.removeEventListener("keydown", trapHandlerCrossmintBound, true);
        trapHandlerCrossmintBound = null;
      }

      function changeMonth(delta) {
        const base = new Date(state.currentDate.getFullYear(), state.currentDate.getMonth(), 1);
        base.setMonth(base.getMonth() + delta);
        state.currentDate = base;
        state.selectedDate = null;
        state.selectedTime = null;
        render();
      }

      function getCalendarItems() {
        const year = state.currentDate.getFullYear();
        const month = state.currentDate.getMonth();
        const firstDayOfMonth = new Date(year, month, 1).getDay();
        const daysInMonth = new Date(year, month + 1, 0).getDate();
        const firstDayIndex = firstDayOfMonth === 0 ? 6 : firstDayOfMonth - 1;

        const items = [];
        for (let i = 0; i < firstDayIndex; i += 1) {
          items.push({ type: "empty", key: "empty-" + i });
        }

        const now = new Date();
        now.setHours(0, 0, 0, 0);

        for (let day = 1; day <= daysInMonth; day += 1) {
          const date = new Date(year, month, day);
          date.setHours(0, 0, 0, 0);
          const isDisabled = date.getTime() < now.getTime();
          const isSelected = !!(state.selectedDate && state.selectedDate.toDateString() === date.toDateString());
          items.push({ type: "day", key: "day-" + day, day: day, date: date, isDisabled: isDisabled, isSelected: isSelected });
        }

        return items;
      }

      function renderMonthHeader() {
        const formatter = new Intl.DateTimeFormat("hu-HU", { month: "long" });
        const monthName = formatter.format(state.currentDate);
        monthYearEl.textContent = state.currentDate.getFullYear() + ". " + monthName;
      }

      function renderDays() {
        while (daysGrid.firstChild) daysGrid.removeChild(daysGrid.firstChild);
        const items = getCalendarItems();

        for (let i = 0; i < items.length; i += 1) {
          const item = items[i];
          const cell = document.createElement("div");
          cell.className = "calendar-day";
          cell.setAttribute("role", "gridcell");

          if (item.type === "empty") {
            cell.classList.add("empty");
            cell.textContent = "";
            daysGrid.appendChild(cell);
            continue;
          }

          cell.textContent = String(item.day);
          cell.dataset.date = String(item.date.getTime());

          if (item.isDisabled) {
            cell.classList.add("disabled");
            cell.setAttribute("aria-disabled", "true");
          } else {
            cell.setAttribute("aria-disabled", "false");
            cell.tabIndex = 0;
          }

          if (item.isSelected) {
            cell.classList.add("selected");
            cell.setAttribute("aria-selected", "true");
          } else {
            cell.setAttribute("aria-selected", "false");
          }

          daysGrid.appendChild(cell);
        }
      }

      function renderTimeSlots() {
        while (timeSlotsEl.firstChild) timeSlotsEl.removeChild(timeSlotsEl.firstChild);
        if (!state.selectedDate) {
          timeSlotsContainer.classList.remove("active");
          return;
        }
        timeSlotsContainer.classList.add("active");

        for (let i = 0; i < availableTimeSlots.length; i += 1) {
          const time = availableTimeSlots[i];
          const slot = document.createElement("div");
          slot.className = "time-slot";
          slot.setAttribute("role", "listitem");
          slot.tabIndex = 0;
          slot.textContent = time;
          slot.dataset.time = time;
          if (state.selectedTime === time) slot.classList.add("selected");
          timeSlotsEl.appendChild(slot);
        }
      }

      function renderConfirmState() {
        const enabled = !!(state.selectedDate && state.selectedTime);
        confirmBookingButton.disabled = !enabled;
      }

      function render() {
        renderMonthHeader();
        renderDays();
        renderTimeSlots();
        renderConfirmState();
      }

      function selectDateFromCell(cell) {
        if (!cell || !cell.dataset || !cell.dataset.date) return;
        const timeMs = Number(cell.dataset.date);
        if (!isFinite(timeMs)) return;
        const date = new Date(timeMs);
        date.setHours(0, 0, 0, 0);
        state.selectedDate = date;
        state.selectedTime = null;
        render();
      }

      function selectTimeFromSlot(slot) {
        if (!slot || !slot.dataset || !slot.dataset.time) return;
        state.selectedTime = slot.dataset.time;
        render();
      }

      function uuid() {
        if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
          return crypto.randomUUID();
        }
        const bytes = new Uint8Array(16);
        crypto.getRandomValues(bytes);
        bytes[6] = (bytes[6] & 0x0f) | 0x40;
        bytes[8] = (bytes[8] & 0x3f) | 0x80;
        const hex = Array.from(bytes).map(function(b) { return b.toString(16).padStart(2, "0"); }).join("");
        return hex.slice(0, 8) + "-" + hex.slice(8, 12) + "-" + hex.slice(12, 16) + "-" + hex.slice(16, 20) + "-" + hex.slice(20);
      }

      async function getConfig() {
        if (configCache) return configCache;
        const response = await fetch("/api/config", {
          method: "GET",
          credentials: "same-origin",
          cache: "no-store"
        });
        if (!response.ok) {
          const text = await response.text().catch(function () { return ""; });
          throw new Error("Config error " + response.status + " " + text);
        }
        const data = await response.json();
        configCache = data;
        return data;
      }

      function CheckoutInner(props) {
        const cfg = props.cfg;
        const payload = props.payload;
        const onClose = props.onClose;
        const checkout = useCrossmintCheckout();
        React.useEffect(function () {
          if (!checkout || !checkout.order) return;
          const ord = checkout.order;
          if (ord.phase === "completed" || ord.phase === "delivery-completed") {
            setTimeout(onClose, 1500);
          }
        }, [checkout, onClose]);
        const collectionId = payload.kind === "small" ? cfg.crossmintCollectionIdSmall : cfg.crossmintCollectionIdBooking;
        const metadata = payload.metadata || {};
        const lineItems = {
          collectionLocator: "crossmint:" + collectionId,
          callData: {
            totalPrice: String(payload.totalPrice),
            quantity: 1,
            metadata: metadata
          }
        };
        const paymentConfig = {
          crypto: { enabled: false },
          fiat: {
            enabled: true,
            defaultCurrency: cfg.fiatCurrency || "eur",
            allowedMethods: {
              card: true,
              applePay: true,
              googlePay: true
            }
          }
        };
        const recipientConfig = payload.recipientWalletAddress ? { walletAddress: payload.recipientWalletAddress } : undefined;
        return React.createElement(CrossmintEmbeddedCheckout, {
          lineItems: lineItems,
          payment: paymentConfig,
          recipient: recipientConfig,
          locale: cfg.locale || "hu-HU"
        });
      }

      function CheckoutApp(props) {
        const payload = props.payload;
        const onClose = props.onClose;
        const stateArr = React.useState(null);
        const cfg = stateArr[0];
        const setCfg = stateArr[1];
        const errArr = React.useState(null);
        const err = errArr[0];
        const setErr = errArr[1];

        React.useEffect(function () {
          let alive = true;
          getConfig()
            .then(function (c) {
              if (!alive) return;
              setCfg(c);
            })
            .catch(function (e) {
              if (!alive) return;
              setErr(e instanceof Error ? e.message : String(e));
            });
          return function () {
            alive = false;
          };
        }, []);

        if (err) {
          return React.createElement("div", { style: { color: "#ff453a", fontSize: "0.95rem", lineHeight: "1.4", padding: "1rem" } }, err);
        }

        if (!cfg) {
          return React.createElement("div", { style: { color: "rgba(235,235,245,0.7)", fontSize: "0.95rem", padding: "1rem" } }, "Betöltés...");
        }

        return React.createElement(
          CrossmintProvider,
          { apiKey: cfg.crossmintClientApiKey },
          React.createElement(
            CrossmintCheckoutProvider,
            null,
            React.createElement(CheckoutInner, { cfg: cfg, payload: payload, onClose: onClose })
          )
        );
      }

      async function openCrossmintCheckout(payload) {
        openCrossmintModal();
        if (!crossmintRoot) {
          crossmintRoot = ReactDOM.createRoot(crossmintMount);
        }
        crossmintRoot.render(React.createElement(CheckoutApp, { payload: payload, onClose: closeCrossmintModal }));
      }

      async function handlePurchase() {
        const purchaseId = uuid();
        const payload = {
          kind: "small",
          totalPrice: "10000",
          metadata: {
            purchaseId: purchaseId,
            product: "kis_csomag",
            amount_huf: 10000,
            createdAt: new Date().toISOString()
          }
        };
        await openCrossmintCheckout(payload);
      }

      async function handleBookingConfirm() {
        if (!state.selectedDate || !state.selectedTime) return;
        const purchaseId = uuid();
        const formattedDate = formatDateHu(state.selectedDate);
        const payload = {
          kind: "booking",
          totalPrice: "25000",
          metadata: {
            purchaseId: purchaseId,
            product: "idopontfoglalas",
            amount_huf: 25000,
            booking_date: formattedDate,
            booking_time: state.selectedTime,
            createdAt: new Date().toISOString()
          }
        };
        closeModal();
        await openCrossmintCheckout(payload);
      }

      openBookingButton.addEventListener("click", openModal);
      purchaseSmallButton.addEventListener("click", function () { handlePurchase(); });
      closeModalButton.addEventListener("click", closeModal);
      prevMonthButton.addEventListener("click", function () { changeMonth(-1); });
      nextMonthButton.addEventListener("click", function () { changeMonth(1); });
      confirmBookingButton.addEventListener("click", function () { handleBookingConfirm(); });

      closeCrossmintButton.addEventListener("click", closeCrossmintModal);

      bookingModal.addEventListener("click", function (event) {
        if (event.target === bookingModal) closeModal();
      });

      crossmintModal.addEventListener("click", function (event) {
        if (event.target === crossmintModal) closeCrossmintModal();
      });

      daysGrid.addEventListener("click", function (event) {
        const target = event.target;
        if (!(target instanceof HTMLElement)) return;
        if (!target.classList.contains("calendar-day")) return;
        if (target.classList.contains("disabled") || target.classList.contains("empty")) return;
        selectDateFromCell(target);
      });

      daysGrid.addEventListener("keydown", function (event) {
        if (event.key !== "Enter" && event.key !== " ") return;
        const target = event.target;
        if (!(target instanceof HTMLElement)) return;
        if (!target.classList.contains("calendar-day")) return;
        if (target.classList.contains("disabled") || target.classList.contains("empty")) return;
        event.preventDefault();
        selectDateFromCell(target);
      });

      timeSlotsEl.addEventListener("click", function (event) {
        const target = event.target;
        if (!(target instanceof HTMLElement)) return;
        if (!target.classList.contains("time-slot")) return;
        selectTimeFromSlot(target);
      });

      timeSlotsEl.addEventListener("keydown", function (event) {
        if (event.key !== "Enter" && event.key !== " ") return;
        const target = event.target;
        if (!(target instanceof HTMLElement)) return;
        if (!target.classList.contains("time-slot")) return;
        event.preventDefault();
        selectTimeFromSlot(target);
      });

      render();
    })();
  </script>
</body>
</html>


